#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { parseOptions } = require('./lib/binary-target');

const ROOT = path.resolve(__dirname, '..');

function generateNativeBundle(options = {}) {
  const input = path.resolve(options.input || path.join(ROOT, 'node_modules', 'better-sqlite3', 'build', 'Release', 'better_sqlite3.node'));
  const output = path.resolve(options.output || path.join(ROOT, 'src', 'native-bundle.js'));
  const platform = options.platform || process.platform;
  const arch = options.arch || process.arch;
  const abi = String(options.abi || process.env.PAPERWEIGHT_BUNDLE_ABI || process.versions.modules);

  if (!fs.existsSync(input)) throw new Error(`better_sqlite3.node not found at ${input}`);

  const data = fs.readFileSync(input);
  const hash = crypto.createHash('sha256').update(data).digest('hex');
  const content = [
    '// AUTO-GENERATED by scripts/generate-native-bundle.js - do not edit by hand.',
    "'use strict';",
    '',
    'module.exports = {',
    `  data: Buffer.from(${JSON.stringify(data.toString('base64'))}, 'base64'),`,
    `  sha256: ${JSON.stringify(hash)},`,
    `  platform: ${JSON.stringify(platform)},`,
    `  arch: ${JSON.stringify(arch)},`,
    `  abi: ${JSON.stringify(abi)},`,
    '};',
    '',
  ].join('\n');

  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, content, 'utf8');
  return { input, output, platform, arch, abi, size: data.length, hash };
}

if (require.main === module) {
  try {
    const result = generateNativeBundle(parseOptions(process.argv.slice(2)));
    console.log(`Generated ${result.output} (${Math.round(result.size / 1024)} KB ${result.platform}/${result.arch}, ABI ${result.abi}).`);
  } catch (err) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }
}

module.exports = { generateNativeBundle };
